/* @autogenerated */
package net.civeira.phylax.feature.observe.store;

import java.io.BufferedWriter;
import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.function.Predicate;
import java.util.stream.Stream;

import org.eclipse.microprofile.config.inject.ConfigProperty;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.extern.slf4j.Slf4j;

/**
 * Store in JSON Lines files, the simplest format for small on premise micros: one directory per day
 * (UTC) with {@code logs.jsonl} and {@code spans.jsonl}. Writing is append only; the retention
 * deletes whole days. Queries read the days of the range, newest first, until the limit.
 */
@ApplicationScoped
@Slf4j
public class JsonlTelemetryStore implements TelemetryStore {

  private static final String LOGS = "logs.jsonl";
  private static final String SPANS = "spans.jsonl";

  private final Path root;
  private final ObjectMapper mapper =
      new ObjectMapper().configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);

  public JsonlTelemetryStore(final @ConfigProperty(name = "app.observe.path",
      defaultValue = "data/observability") String path) {
    this.root = Path.of(path);
  }

  @Override
  public synchronized void appendLogs(final List<ObsLog> logs) {
    append(LOGS, logs, ObsLog::ts);
  }

  @Override
  public synchronized void appendSpans(final List<ObsSpan> spans) {
    append(SPANS, spans, ObsSpan::ts);
  }

  @Override
  public List<ObsLog> logs(final TelemetryQuery query) {
    Predicate<ObsLog> filter = log -> inRange(log.ts(), query)
        && (query.getSources().isEmpty() || query.getSources().contains(log.src()))
        && query.getMinLevel().map(min -> Levels.atLeast(log.level(), min)).orElse(true)
        && (!query.isErrors() || Levels.atLeast(log.level(), "ERROR"))
        && query.getTraceId().map(id -> id.equals(log.traceId())).orElse(true)
        && query.getText().map(text -> contains(text, log.msg(), log.logger(), log.error(),
            String.valueOf(log.attrs()))).orElse(true);
    return read(LOGS, ObsLog.class, query, filter, Comparator.comparingLong(ObsLog::ts).reversed());
  }

  @Override
  public List<ObsSpan> spans(final TelemetryQuery query) {
    Predicate<ObsSpan> filter = span -> inRange(span.ts(), query)
        && (query.getSources().isEmpty() || query.getSources().contains(span.src()))
        && (!query.isErrors() || span.isError())
        && query.getTraceId().map(id -> id.equals(span.traceId())).orElse(true) && query.getText()
            .map(text -> contains(text, span.name(), String.valueOf(span.attrs()))).orElse(true);
    return read(SPANS, ObsSpan.class, query, filter,
        Comparator.comparingLong(ObsSpan::ts).reversed());
  }

  @Override
  public List<ObsSpan> trace(final String traceId, final long from, final long to) {
    TelemetryQuery query = TelemetryQuery.builder().from(from).to(to)
        .traceId(java.util.Optional.of(traceId)).minLevel(java.util.Optional.empty())
        .text(java.util.Optional.empty()).limit(5_000).build();
    return read(SPANS, ObsSpan.class, query, span -> traceId.equals(span.traceId()),
        Comparator.comparingLong(ObsSpan::ts));
  }

  /**
   * Deletes the logs and the spans of the days out of their retention (each kind has its own), the
   * days left empty and then, while the store is above {@code maxDiskMb}, the oldest days. The
   * retention of each source is not applied here: the files of a day hold every source.
   */
  @Override
  public synchronized void purge(final RetentionPolicy policy) {
    if (!Files.isDirectory(root)) {
      return;
    }
    LocalDate today = LocalDate.now(ZoneOffset.UTC);
    LocalDate logsLimit = today.minusDays(policy.logsDays());
    LocalDate spansLimit = today.minusDays(policy.tracesDays());
    for (Path dir : days()) {
      LocalDate day = dayOf(dir);
      if (day.isBefore(logsLimit)) {
        deleteFile(dir.resolve(LOGS));
      }
      if (day.isBefore(spansLimit)) {
        deleteFile(dir.resolve(SPANS));
      }
      if (isEmpty(dir)) {
        delete(dir);
      }
    }
    long limit = policy.maxDiskMb() * 1024 * 1024;
    if (limit <= 0) {
      return;
    }
    List<Path> days = days();
    long size = days.stream().mapToLong(JsonlTelemetryStore::size).sum();
    for (Path dir : days) {
      if (size <= limit || !dayOf(dir).isBefore(today)) {
        break;
      }
      long freed = size(dir);
      log.warn("The observability store is above {} MB: deleting the day {}", policy.maxDiskMb(),
          dir.getFileName());
      delete(dir);
      size -= freed;
    }
  }

  /** The day directories, oldest first. */
  private List<Path> days() {
    try (Stream<Path> days = Files.list(root)) {
      return days.filter(Files::isDirectory).filter(dir -> null != dayOf(dir))
          .sorted(Comparator.comparing(JsonlTelemetryStore::dayOf)).toList();
    } catch (IOException ex) {
      log.warn("Unable to list {}: {}", root, ex.getMessage());
      return List.of();
    }
  }

  private static LocalDate dayOf(final Path dir) {
    try {
      return LocalDate.parse(dir.getFileName().toString());
    } catch (RuntimeException ex) {
      return null;
    }
  }

  private static long size(final Path dir) {
    try (Stream<Path> files = Files.walk(dir)) {
      return files.filter(Files::isRegularFile).mapToLong(path -> {
        try {
          return Files.size(path);
        } catch (IOException ex) {
          return 0;
        }
      }).sum();
    } catch (IOException ex) {
      return 0;
    }
  }

  private static boolean isEmpty(final Path dir) {
    try (Stream<Path> files = Files.list(dir)) {
      return files.findAny().isEmpty();
    } catch (IOException ex) {
      return false;
    }
  }

  private void deleteFile(final Path file) {
    try {
      Files.deleteIfExists(file);
    } catch (IOException ex) {
      log.warn("Unable to delete {}: {}", file, ex.getMessage());
    }
  }

  private <T> void append(final String file, final List<T> items,
      final java.util.function.ToLongFunction<T> ts) {
    if (items.isEmpty()) {
      return;
    }
    try {
      for (T item : items) {
        Path dir = root.resolve(day(ts.applyAsLong(item)).toString());
        Files.createDirectories(dir);
        try (BufferedWriter writer = Files.newBufferedWriter(dir.resolve(file),
            StandardCharsets.UTF_8, StandardOpenOption.CREATE, StandardOpenOption.APPEND)) {
          writer.write(mapper.writeValueAsString(item));
          writer.newLine();
        }
      }
    } catch (IOException ex) {
      throw new UncheckedIOException(ex);
    }
  }

  private <T> List<T> read(final String file, final Class<T> type, final TelemetryQuery query,
      final Predicate<T> filter, final Comparator<T> order) {
    List<T> result = new ArrayList<>();
    LocalDate first = day(query.getFrom());
    for (LocalDate day = day(query.getTo()); !day.isBefore(first); day = day.minusDays(1)) {
      Path path = root.resolve(day.toString()).resolve(file);
      if (!Files.exists(path)) {
        continue;
      }
      List<T> ofDay = new ArrayList<>();
      try (Stream<String> lines = Files.lines(path, StandardCharsets.UTF_8)) {
        lines.forEach(line -> parse(line, type).filter(filter).ifPresent(ofDay::add));
      } catch (IOException | UncheckedIOException ex) {
        log.warn("Unable to read {}: {}", path, ex.getMessage());
      }
      ofDay.sort(order);
      result.addAll(ofDay);
      if (result.size() >= query.getLimit()) {
        break;
      }
    }
    result.sort(order);
    return result.size() > query.getLimit() ? result.subList(0, query.getLimit()) : result;
  }

  private <T> java.util.Optional<T> parse(final String line, final Class<T> type) {
    if (line.isBlank()) {
      return java.util.Optional.empty();
    }
    try {
      return java.util.Optional.of(mapper.readValue(line, type));
    } catch (IOException ex) {
      // A line cut by a crash is skipped
      return java.util.Optional.empty();
    }
  }

  private static boolean inRange(final long ts, final TelemetryQuery query) {
    return ts >= query.getFrom() && ts < query.getTo();
  }

  private static boolean contains(final String text, final String... values) {
    String needle = text.toLowerCase(Locale.ROOT);
    for (String value : values) {
      if (null != value && value.toLowerCase(Locale.ROOT).contains(needle)) {
        return true;
      }
    }
    return false;
  }

  private static LocalDate day(final long epochMillis) {
    return Instant.ofEpochMilli(epochMillis).atZone(ZoneOffset.UTC).toLocalDate();
  }

  private void delete(final Path dir) {
    try (Stream<Path> files = Files.walk(dir)) {
      files.sorted(Comparator.reverseOrder()).forEach(path -> {
        try {
          Files.deleteIfExists(path);
        } catch (IOException ex) {
          log.warn("Unable to delete {}: {}", path, ex.getMessage());
        }
      });
    } catch (IOException ex) {
      log.warn("Unable to delete {}: {}", dir, ex.getMessage());
    }
  }
}
